mapper.select:
SELECT COUNT(*)
FROM TB_GHOST_COMMENT
WHERE GHOST_ID=#{ghostId}

mapper.delete:
DELETE FROM TB_GHOST_COMMENT
WHERE COMMENT_ID=#{commentId}
	AND GHOST_ID=#{ghostId}

mapper.update:
UPDATE TB_GHOST_COMMENT
SET CONTENT=#{comment.content}
WHERE COMMENT_ID=#{comment.commentId}
	AND GHOST_ID=#{ghostId}
